26		Deadline  *int64 `json:"deadline"`
27	}
28	
29	type periodicRequest struct {
30		Tasks *[]periodicTaskIn `json:"tasks"`
31	}
32	
33	type periodicTask struct {
34		id        string
35		priority  int64
36		execution int64
37		period    int64
38		deadline  int64
39	}
40	
41	type periodicTaskResult struct {
42		ID             string `json:"id"`
