14	
15	func postMutex(t *testing.T, body, contentType string) *httptest.ResponseRecorder {
16		t.Helper()
17		rec := httptest.NewRecorder()
18		r := httptest.NewRequest(http.MethodPost, mutexAnalyzePath, strings.NewReader(body))
19		if contentType != "" {
20			r.Header.Set("Content-Type", contentType)
21		}
22		Handler().ServeHTTP(rec, r)
23		return rec
24	}
25	
26	func mutexOK(t *testing.T, body string) mutexResponse {
27		t.Helper()
28		rec := postMutex(t, body, "application/json")
29		if rec.Code != http.StatusOK {
30			t.Fatalf("status = %d, want 200; body: %s", rec.Code, rec.Body.String())
31		}
32		var resp mutexResponse
33		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
34			t.Fatalf("response is not JSON: %v", err)
35		}
36		return resp
37	}
38	
39	func mtask(id string, prio, rel, dead int64, actions ...string) string {
40		return `{"id":"` + id + `","priority":` + strconv.FormatInt(prio, 10) +
41			`,"release":` + strconv.FormatInt(rel, 10) +
42			`,"deadline":` + strconv.FormatInt(dead, 10) +
43			`,"actions":[` + strings.Join(actions, ",") + `]}`
44	}
45	
46	func mrun(n int64) string     { return `{"run":` + strconv.FormatInt(n, 10) + `}` }
47	func mlock(m string) string   { return `{"lock":"` + m + `"}` }
48	func munlock(m string) string { return `{"unlock":"` + m + `"}` }
49	
50	func TestMutexPriorityInheritance(t *testing.T) {
51		// A (prio 2) holds M from t=0. B (prio 0) blocks on M at t=3: A inherits
52		// prio 0, so C (prio 1, released at 5) cannot preempt. At t=6 M hands off
53		// to B; B finishes, then C runs.
54		body := `{"horizon":30,"tasks":[` +
55			mtask("A", 2, 0, 30, mlock("M"), mrun(6), munlock("M")) + "," +
56			mtask("B", 0, 3, 30, mlock("M"), mrun(2), munlock("M")) + "," +
57			mtask("C", 1, 5, 30, mrun(3)) + "]}"
58		resp := mutexOK(t, body)
59		if resp.Status != "completed" {
60			t.Fatalf("status = %q, want completed: %+v", resp.Status, resp)
61		}
62		want := []mutexTimelineInterval{
63			{TaskID: "A", Start: 0, End: 3, EffectivePriority: 2},
64			{TaskID: "A", Start: 3, End: 6, EffectivePriority: 0},
65			{TaskID: "B", Start: 6, End: 8, EffectivePriority: 0},
66			{TaskID: "C", Start: 8, End: 11, EffectivePriority: 1},
67		}
68		if len(resp.Timeline) != len(want) {
69			t.Fatalf("timeline = %+v, want %+v", resp.Timeline, want)
70		}
71		for i := range want {
72			if resp.Timeline[i] != want[i] {
73				t.Fatalf("timeline[%d] = %+v, want %+v", i, resp.Timeline[i], want[i])
74			}
75		}
76		a, b, c := resp.Results[0], resp.Results[1], resp.Results[2]
77		if a.State != "completed" || a.Executed != 6 || a.Completion == nil || *a.Completion != 6 || a.BlockedOn != nil {
78			t.Fatalf("A result = %+v", a)
79		}
80		if b.State != "completed" || b.Executed != 2 || b.Completion == nil || *b.Completion != 8 {
81			t.Fatalf("B result = %+v", b)
82		}
