430	// ---- Differential test against an independent tick-by-tick reference ------
431	
432	type refTask struct {
433		id                      string
434		prio, release, deadline int64
435		acts                    []mutexAction
436	}
437	
438	type refSim struct {
439		tasks     []refTask
440		n         int
441		horizon   int64
442		owner     map[string]int
443		waiters   map[string][]int
444		held      []map[string]bool
445		blockedM  []string
446		blockTime []int64
447		pc        []int
448		rem       []int64
449		released  []bool
450		done      []bool
451		executed  []int64
452		finish    []*int64
453		eff       []int64
454		now       int64
455		current   int
456		segs      []mutexSegment
457		dead      bool
458		deadAt    int64
459		cycle     []int
460	}
461	
462	func refRun(tasks []refTask, horizon int64) mutexResponse {
463		r := &refSim{
464			tasks: tasks, n: len(tasks), horizon: horizon,
465			owner: map[string]int{}, waiters: map[string][]int{},
466			current: -1,
467		}
468		r.held = make([]map[string]bool, r.n)
469		r.blockedM = make([]string, r.n)
470		r.blockTime = make([]int64, r.n)
471		r.pc = make([]int, r.n)
472		r.rem = make([]int64, r.n)
473		r.released = make([]bool, r.n)
474		r.done = make([]bool, r.n)
475		r.executed = make([]int64, r.n)
476		r.finish = make([]*int64, r.n)
477		r.eff = make([]int64, r.n)
478		for i := range tasks {
479			r.held[i] = map[string]bool{}
480			r.eff[i] = tasks[i].prio
481		}
482	
483		for t := int64(0); t < horizon; t++ {
484			r.now = t
485			for i := 0; i < r.n; i++ {
486				if tasks[i].release == t {
487					r.released[i] = true
488				}
489			}
490			if !r.settlePoint() {
491				return r.build()
492			}
493			if r.current == -1 {
494				continue
495			}
496			cur := r.current
497			r.rem[cur]--
498			r.executed[cur]++
499			r.segs = append(r.segs, mutexSegment{index: cur, start: t, end: t + 1, eff: r.eff[cur]})
500			if r.rem[cur] == 0 {
501				// Keep current set: at the next instant settlePoint drains this
502				// task's zero-duration chain before any (re)scheduling, matching
503				// "current task's zero-time actions first, then schedule".
504				r.pc[cur]++
505			}
506		}
507	
508		// Boundary instant at t == horizon: drain the just-finished task's
509		// zero-duration chain once (matches the boundary rule).
510		if r.current != -1 {
511			i := r.current
512			if !r.done[i] && r.blockedM[i] == "" && r.rem[i] == 0 {
513				r.now = horizon
514				if r.settle(i) {
515					r.dead = true
516					r.deadAt = horizon
517				}
518			}
519		}
520		return r.build()
521	}
522	
523	// settlePoint performs all zero-time resolution at the current instant and
524	// leaves r.current on the task that owns the CPU during the next tick.
525	func (r *refSim) settlePoint() bool {
526		for {
527			if r.current != -1 {
528				if r.settle(r.current) {
529					r.dead = true
530					r.deadAt = r.now
531					return false
532				}
533				if r.done[r.current] || r.blockedM[r.current] != "" || r.rem[r.current] == 0 {
534					r.current = -1
535				}
536			}
537			best := r.pick()
538			if r.current == -1 {
539				if best == -1 {
540					return true
541				}
542				r.current = best
543				if r.settle(best) {
544					r.dead = true
545					r.deadAt = r.now
546					return false
547				}
548				if r.done[best] || r.blockedM[best] != "" || r.rem[best] == 0 {
549					r.current = -1
550					continue
551				}
552			}
553			// Same-instant preemption: the selected task's zero-duration chain
554			// can hand a mutex to a strictly higher effective-priority task.
555			resolved := false
556			for !resolved {
557				b := r.pick()
558				if b != -1 && b != r.current && r.eff[b] < r.eff[r.current] {
559					r.current = b
560					if r.settle(b) {
561						r.dead = true
562						r.deadAt = r.now
563						return false
564					}
565					if r.done[b] || r.blockedM[b] != "" || r.rem[b] == 0 {
566						r.current = -1
567						break
568					}
569					continue
570				}
571				resolved = true
572			}
573			if r.current == -1 {
574				continue
575			}
576			return true
577		}
578	}
579	
580	func (r *refSim) settle(i int) bool {
581		tk := r.tasks[i]
582		for r.pc[i] < len(tk.acts) {
583			a := tk.acts[r.pc[i]]
584			switch a.kind {
585			case mutexActRun:
586				if r.rem[i] == 0 {
587					r.rem[i] = a.run
588				}
589				return false
590			case mutexActLock:
591				if owner, ok := r.owner[a.name]; ok {
592					if owner == i {
593						r.pc[i]++
594						continue
595					}
596					cycle := r.findCycle(i, owner)
597					r.blockedM[i] = a.name
598					r.blockTime[i] = r.now
599					r.waiters[a.name] = append(r.waiters[a.name], i)
600					if cycle != nil {
601						r.cycle = cycle
602						return true
603					}
604					r.recompute()
605					return false
606				}
607				r.owner[a.name] = i
608				r.held[i][a.name] = true
609				r.pc[i]++
610			case mutexActUnlock:
611				r.give(a.name, i)
612				r.pc[i]++
613			}
614		}
615		r.done[i] = true
616		at := r.now
617		r.finish[i] = &at
618		return false
619	}
620	
621	func (r *refSim) findCycle(waiter, holder int) []int {
622		chain := []int{holder}
623		cur := holder
624		for {
625			if r.blockedM[cur] == "" {
626				return nil
627			}
628			next := r.owner[r.blockedM[cur]]
629			if next == waiter {
630				break
631			}
632			chain = append(chain, next)
633			cur = next
634		}
635		cycle := append([]int{waiter}, chain...)
636		first := 0
637		for k := 1; k < len(cycle); k++ {
638			if cycle[k] < cycle[first] {
639				first = k
640			}
641		}
642		return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
643	}
644	
645	func (r *refSim) give(m string, from int) {
646		ws := r.waiters[m]
647		delete(r.held[from], m)
648		if len(ws) == 0 {
649			delete(r.owner, m)
650			r.recompute()
651			return
652		}
653		w := ws[0]
654		for _, x := range ws[1:] {
655			if r.eff[x] < r.eff[w] ||
656				(r.eff[x] == r.eff[w] && r.blockTime[x] < r.blockTime[w]) ||
657				(r.eff[x] == r.eff[w] && r.blockTime[x] == r.blockTime[w] && x < w) {
658				w = x
659			}
660		}
661		r.owner[m] = w
662		r.held[w][m] = true
663		var rest []int
664		for _, x := range ws {
665			if x != w {
666				rest = append(rest, x)
667			}
668		}
669		r.waiters[m] = rest
670		r.blockedM[w] = ""
671		r.recompute()
672	}
673	
674	func (r *refSim) recompute() {
675		color := make([]int, r.n)
676		var walk func(int) int64
677		walk = func(i int) int64 {
678			if color[i] == 2 {
679				return r.eff[i]
680			}
681			color[i] = 1
682			best := r.tasks[i].prio
683			for m := range r.held[i] {
684				for _, w := range r.waiters[m] {
685					if v := walk(w); v < best {
686						best = v
687					}
688				}
689			}
690			color[i] = 2
691			r.eff[i] = best
692			return best
693		}
694		for i := 0; i < r.n; i++ {
695			walk(i)
696		}
697	}
698	
699	func (r *refSim) pick() int {
700		best := -1
701		for i := 0; i < r.n; i++ {
702			if !r.released[i] || r.done[i] || r.blockedM[i] != "" {
703				continue
704			}
705			if best == -1 {
706				best = i
707				continue
708			}
709			a, b := r.tasks[i], r.tasks[best]
710			if r.eff[i] < r.eff[best] ||
711				(r.eff[i] == r.eff[best] && a.release < b.release) ||
712				(r.eff[i] == r.eff[best] && a.release == b.release && i < best) {
713				best = i
714			}
715		}
716		return best
717	}
718	
719	func (r *refSim) build() mutexResponse {
720		resp := mutexResponse{Timeline: []mutexTimelineInterval{}}
721		for _, seg := range r.segs {
722			last := len(resp.Timeline) - 1
723			if last >= 0 &&
724				resp.Timeline[last].TaskID == r.tasks[seg.index].id &&
725				resp.Timeline[last].EffectivePriority == seg.eff &&
726				resp.Timeline[last].End == seg.start {
727				resp.Timeline[last].End = seg.end
728				continue
729			}
730			resp.Timeline = append(resp.Timeline, mutexTimelineInterval{
731				TaskID: r.tasks[seg.index].id, Start: seg.start, End: seg.end, EffectivePriority: seg.eff,
732			})
733		}
734		resp.Results = make([]mutexTaskResult, r.n)
735		allDone := true
736		for i, tk := range r.tasks {
737			state := "ready"
738			switch {
739			case r.done[i]:
740				state = "completed"
741			case r.blockedM[i] != "":
742				state = "blocked"
743			case !r.released[i]:
744				state = "unreleased"
745			}
746			if state != "completed" {
747				allDone = false
748			}
749			var bo *string
750			if state == "blocked" {
751				m := r.blockedM[i]
752				bo = &m
753			}
754			var ds string
755			switch c := r.finish[i]; {
756			case c != nil && *c <= tk.deadline:
757				ds = "met"
758			case c != nil:
759				ds = "missed"
760			case tk.deadline <= r.horizon:
761				ds = "missed"
762			default:
763				ds = "pending"
764			}
765			resp.Results[i] = mutexTaskResult{
766				Executed: r.executed[i], Completion: r.finish[i],
767				State: state, BlockedOn: bo, DeadlineStatus: ds,
768			}
769		}
770		switch {
771		case r.dead:
772			resp.Status = "deadlocked"
773		case allDone:
774			resp.Status = "completed"
775		default:
776			resp.Status = "horizon"
777		}
778		if r.dead {
779			at := r.deadAt
780			resp.DeadlockAt = &at
781			resp.Cycle = make([]string, len(r.cycle))
782			for k, idx := range r.cycle {
783				resp.Cycle[k] = r.tasks[idx].id
784			}
785		}
786		return resp
787	}
788	
789	func TestMutexDifferential(t *testing.T) {
790		seed := time.Now().UnixNano()
791		rng := rand.New(rand.NewSource(seed))
792		names := []string{"m0", "m1", "m2"}
793		for iter := 0; iter < 2000; iter++ {
794			n := 1 + rng.Intn(5)
795			horizon := int64(2 + rng.Intn(24))
796			got := make([]mutexTask, n)
797			ref := make([]refTask, n)
798			used := map[string]bool{}
799			for i := 0; i < n; i++ {
800				var id string
801				for {
802					id = "t" + strconv.Itoa(rng.Intn(40))
803					if !used[id] {
804						used[id] = true
805						break
806					}
807				}
808				prio := int64(rng.Intn(4))
809				rel := int64(rng.Intn(int(horizon)))
810				dead := rel + int64(1+rng.Intn(30))
811				nacts := 1 + rng.Intn(8)
812				acts := make([]mutexAction, 0, nacts+3)
813				var open []string
814				for k := 0; k < nacts; k++ {
815					choice := rng.Intn(10)
816					if choice < 6 {
817						acts = append(acts, mutexAction{kind: mutexActRun, run: int64(1 + rng.Intn(5))})
818						continue
819					}
820					if choice < 8 {
821						m := names[rng.Intn(len(names))]
822						held := false
823						for _, h := range open {
824							if h == m {
825								held = true
826							}
827						}
828						if held {
829							acts = append(acts, mutexAction{kind: mutexActRun, run: 1})
830						} else {
831							acts = append(acts, mutexAction{kind: mutexActLock, name: m})
832							open = append(open, m)
833						}
834						continue
835					}
836					if len(open) == 0 {
837						acts = append(acts, mutexAction{kind: mutexActRun, run: 1})
838					} else {
839						j := rng.Intn(len(open))
840						m := open[j]
841						open = append(open[:j], open[j+1:]...)
842						acts = append(acts, mutexAction{kind: mutexActUnlock, name: m})
843					}
844				}
845				// Close any still-held mutexes so the program is statically valid.
846				for j := len(open) - 1; j >= 0; j-- {
847					acts = append(acts, mutexAction{kind: mutexActUnlock, name: open[j]})
848				}
849				got[i] = mutexTask{id: id, priority: prio, release: rel, deadline: dead, actions: acts}
850				ref[i] = refTask{id: id, prio: prio, release: rel, deadline: dead, acts: acts}
851			}
852	
853			want := refRun(ref, horizon)
854			resp := simulateMutex(got, horizon)
855	
856			if resp.Status != want.Status {
857				t.Fatalf("iter %d seed %d: status %q vs %q\ngot tl %+v", iter, seed, resp.Status, want.Status, resp.Timeline)
858			}
859			if len(resp.Timeline) != len(want.Timeline) {
860				t.Fatalf("iter %d seed %d: timeline len %d vs %d\ngot %+v\nref %+v",
861					iter, seed, len(resp.Timeline), len(want.Timeline), resp.Timeline, want.Timeline)
862			}
863			for k := range want.Timeline {
864				if resp.Timeline[k] != want.Timeline[k] {
865					t.Fatalf("iter %d seed %d: tl[%d] %+v vs %+v", iter, seed, k, resp.Timeline[k], want.Timeline[k])
866				}
867			}
868			for i := range want.Results {
869				g, w := resp.Results[i], want.Results[i]
870				if g.Executed != w.Executed || g.State != w.State || g.DeadlineStatus != w.DeadlineStatus {
871					t.Fatalf("iter %d seed %d: %s result %+v vs %+v", iter, seed, ref[i].id, g, w)
872				}
873				if (g.Completion == nil) != (w.Completion == nil) ||
874					(g.Completion != nil && *g.Completion != *w.Completion) {
875					t.Fatalf("iter %d seed %d: %s completion %v vs %v", iter, seed, ref[i].id, g.Completion, w.Completion)
876				}
877				if (g.BlockedOn == nil) != (w.BlockedOn == nil) ||
878					(g.BlockedOn != nil && *g.BlockedOn != *w.BlockedOn) {
879					t.Fatalf("iter %d seed %d: %s blockedOn %v vs %v", iter, seed, ref[i].id, g.BlockedOn, w.BlockedOn)
880				}
881			}
882			if (resp.DeadlockAt == nil) != (want.DeadlockAt == nil) ||
883				(resp.DeadlockAt != nil && *resp.DeadlockAt != *want.DeadlockAt) {
884				t.Fatalf("iter %d seed %d: deadlockAt %v vs %v", iter, seed, resp.DeadlockAt, want.DeadlockAt)
885			}
886			if strings.Join(resp.Cycle, ",") != strings.Join(want.Cycle, ",") {
887				t.Fatalf("iter %d seed %d: cycle %v vs %v", iter, seed, resp.Cycle, want.Cycle)
888			}
889		}
890	}
