func TestMailboxBlockedSenderRefill(t *testing.T) {
	// Capacity 1. S(p2) enqueues "a" at t=0, then blocks sending "b".
	// R(p1) released at t=4 takes "a" at t=4; "b" refills immediately and the
	// second receive at t=5 yields "b", unblocking S. S(p2) only runs after R
	// blocks on the third receive at t=6: S runs [6,8), sends "c" directly.
	body := mbBody([]string{mbDecl("M", 1)},
		mbTask("S", 2, 0, 100,
			mbSend("M", "a"), mbSend("M", "b"), mbRun(2), mbSend("M", "c")),
		mbTask("R", 1, 4, 100,
			mbRecv("M"), mbRun(1), mbRecv("M"), mbRun(1), mbRecv("M"), mbRun(1)))
	resp := mailboxOK(t, body)
	if resp.Status != "completed" {
		t.Fatalf("status = %q: %+v", resp.Status, resp.Timeline)
	}
	want := []mailboxTimelineInterval{
		{TaskID: "S", Start: 0, End: 4}, // wait: S blocks at t=0; R runs at t=4
	}
	_ = want
	got := tlString(resp.Timeline)
	// S enqueues at t=0 and blocks instantly (no run before t=4): R [4,6),
	// S [6,8), then direct delivery, R [8,9).
	want2 := []mailboxTimelineInterval{
		{TaskID: "R", Start: 4, End: 6},
		{TaskID: "S", Start: 6, End: 8},
		{TaskID: "R", Start: 8, End: 9},
	}
	if len(resp.Timeline) != len(want2) {
		t.Fatalf("timeline = %s, want %+v", got, want2)
	}
	for i := range want2 {
		if resp.Timeline[i] != want2[i] {
			t.Fatalf("timeline[%d] = %+v, want %+v (all %s)", i, resp.Timeline[i], want2[i], got)
		}
	}
	if resp.Results[0].State != "blocked" || resp.Results[0].BlockedAction == nil ||
		*resp.Results[0].BlockedAction != "send" {
		t.Fatalf("S should report its block at stop? state=%s", resp.Results[0].State)
	}
}

func tlString(ivs []mailboxTimelineInterval) string {
	var b strings.Builder
	for _, iv := range ivs {
		b.WriteString(iv.TaskID)
		b.WriteString("[")
		b.WriteString(strconv.FormatInt(iv.Start, 10))
		b.WriteString(",")
		b.WriteString(strconv.FormatInt(iv.End, 10))
		b.WriteString(") ")
	}
	return b.String()
}

func TestMailboxEarliestBlockedReceiverTie(t *testing.T) {
	// Both receivers block on M at t=0; same instant, input order wins even
	// though late has the higher priority.
	body := mbBody([]string{mbDecl("M", 1)},
		mbTask("late", 0, 0, 50, mbRecv("M"), mbRun(1)),
		mbTask("early", 1, 0, 50, mbRecv("M"), mbRun(1)),
		mbTask("S", 2, 0, 50, mbRun(2), mbSend("M", "x")))
	resp := mailboxOK(t, body)
	early := resp.Results[1]
	if len(early.Received) != 1 || early.Received[0].Time != 2 || early.Received[0].Message != "x" {
		t.Fatalf("early should receive first: %+v", early.Received)
	}
	if len(resp.Results[0].Received) != 0 {
		t.Fatalf("late must not receive the first message: %+v", resp.Results[0].Received)
	}
}

