func TestMailboxEarliestBlockedReceiverAcrossTime(t *testing.T) {
	// R1(p3) blocks on M at t=0; R2(p2, higher priority) blocks only at t=2.
	// S sends at t=6: the earliest blocker R1 must receive even though R2 has
	// the better priority.
