				nacts := 1+rng.Intn(9)
				for k:=0;k<nacts;k++ {
					switch rng.Intn(10) {
					case 0,1,2,3: rng.Intn(5)
					case 4,5,6: rng.Intn(len(names)); rng.Intn(4)
					default: rng.Intn(len(names))
					}
				}
