			}
			continue
		}
		fmt.Printf("horizon=%d n=%d\n", horizon, n)
		for i := 0; i < n; i++ {
			var id string
			for { id = "t"+strconv.Itoa(rng.Intn(40)); if !used[id] { used[id]=true; break } }
